// SAFE: Decrementing Signed Counter
// Standard loop termination when j becomes -1.
for (int j = 5; j >= 0; --j) {
    // ...
}

// DANGER: Decrementing Unsigned Counter (Underflow Trap)
// Note: size_t is unsigned (e.g., result of .size())
size_t N = 5;
for (size_t i = N; i >= 0; --i) {
    // i >= 0 is ALWAYS TRUE for unsigned types.
    // i underflows (0 -> SIZE_MAX). Infinite loop.
}

// FIX: Change condition to check against max value
for (size_t k = N; k-- > 0; ) {
    // Executes N times, stops when k reaches 0 after decrement.
}
